#!/usr/bin/env python3
"""工具处理程序 — LLM 调用工具时运行的代码。"""
import json
import math
import os
import glob
import numpy as np
import sys
import argparse
from .data import fetch_phases_cleaned
from .physics import Phase
from .engine import KineticEngine
from pymatgen.core import Composition

# ── MP API key: resolved lazily (import must not require credentials) ─────
from .. import gate as _gate  # noqa: E402  (lazy key helper lives in the gate)

API_KEY = None


def _api_key(required: bool = True):
    global API_KEY
    if API_KEY is None:
        API_KEY = _gate.load_api_key(required=required)
    return API_KEY

class SimParams:
    def __init__(self, args: dict):
        # 你的 SimParams 已经完美支持接收字典了！
        self.sys = args.get('sys', 'Ba-Ti-O')
        
        # 智能处理前驱体：如果是字符串，按照逗号分割；如果是列表，直接保留拼成逗号字符串
        precs = args.get('precursors', 'BaO,TiO2')
        if isinstance(precs, list):
            self.precursors = ','.join(precs)
        else:
            self.precursors = precs
            
        self.Tmin = args.get('Tmin', 1200)
        self.Tmax = args.get('Tmax', 1400)
        self.steps = args.get('steps', 0)
        self.k = args.get('k', 20.0)

# ==========================================
# 核心引擎：只接收纯净的 Python 字典
# ==========================================
def simulate(args_dict: dict) -> str:
    """运行固态反应模拟。只处理计算逻辑。"""    
    try:
        args = SimParams(args_dict)
        
        # Delete ALL stale caches
        for f in glob.glob("S_network_cache_*.npy") + glob.glob("S_sorted_*.npy"):
            os.remove(f)

        # 1. Fetch data and init engine
        phases_raw = fetch_phases_cleaned(args.sys, _api_key())
        engine = KineticEngine([Phase(d) for d in phases_raw], T=args.Tmin)
        
        # 2. Setup initial concentrations
        precursor_list = args.precursors.split(',')
        c_current = np.zeros(engine.N)
        for p_entry in precursor_list:
            if ':' in p_entry:
                p_name, p_amt = p_entry.split(':')
                p_amt = float(p_amt)
            else:
                p_name, p_amt = p_entry, 1.0
            
            std = Composition(p_name).reduced_formula
            if std in engine.phase_idx:
                idx = engine.phase_idx[std]
                c_current[idx] = p_amt  
            else:
                pass

        # 3. Run successive temperature sweep
        T_array = np.linspace(args.Tmin, args.Tmax, args.steps if args.steps > 0 else 40)
        results = {name: [] for name in set(engine.names)}
        
        def dwell_steps(T, Ea=0.5, kB=8.617333262e-5, ref_T=1500, base_steps=8000):
            factor = np.exp(Ea / (kB * T)) / np.exp(Ea / (kB * ref_T))
            steps = int(base_steps * factor)
            return max(2000, min(20000, steps))

        for T in T_array:
            steps = args.steps if args.steps > 0 else dwell_steps(T)
            c_current = engine.evolve_at_T(c_current, T, max_steps=steps, k_base=args.k)
            
            current_totals = {}
            for i, name in enumerate(engine.names):
                current_totals[name] = current_totals.get(name, 0.0) + c_current[i]
                
            for name in results.keys():
                results[name].append(current_totals.get(name, 0.0))
                
        filtered_results = {}
        for name, vals in results.items():
            if any(v > 1e-1 for v in vals):
                filtered_results[name] = vals
                
        return json.dumps({"T_array": T_array.tolist(), "results": filtered_results})
        
    except Exception as e:
        return json.dumps({"error": str(e)})


